//! Report account balances from a ledger file.

use std::collections::HashMap;
use std::env;
use std::fs;
use std::process;

/// Parse an unsigned decimal amount with two fraction digits into cents.
fn to_cents(amount: &str) -> Option<i128> {
    let (whole, frac) = amount.split_once('.')?;
    if whole.is_empty()
        || frac.len() != 2
        || !whole.bytes().all(|b| b.is_ascii_digit())
        || !frac.bytes().all(|b| b.is_ascii_digit())
    {
        return None;
    }
    let whole: i128 = whole.parse().ok()?;
    let frac: i128 = frac.parse().ok()?;
    whole.checked_mul(100)?.checked_add(frac)
}

fn format_cents(cents: i128) -> String {
    let sign = if cents < 0 { "-" } else { "" };
    let cents = cents.unsigned_abs();
    format!("{}{}.{:02}", sign, cents / 100, cents % 100)
}

fn fail(message: &str) -> ! {
    eprintln!("{}", message);
    process::exit(1);
}

fn main() {
    let path = env::args().nth(1).unwrap_or_else(|| fail("usage: ledger <path>"));
    let text = fs::read_to_string(&path).unwrap_or_else(|e| fail(&format!("{}: {}", path, e)));
    let mut lines = text.lines();

    let header: Vec<&str> = lines.next().unwrap_or("").split_whitespace().collect();
    let n: usize = match header.as_slice() {
        ["ledger", count] => count.parse().unwrap_or_else(|_| fail("bad header")),
        _ => fail("bad header"),
    };

    let mut balances: HashMap<String, i128> = HashMap::new();
    for k in 1..=n {
        let line = lines.next().unwrap_or_else(|| fail("missing transaction line"));
        let fields: Vec<&str> = line.split_whitespace().collect();
        let [account, kind, amount] = fields.as_slice() else {
            println!("ERROR line {}", k);
            return;
        };
        let sign = match *kind {
            "credit" => 1,
            "debit" => -1,
            _ => {
                println!("ERROR line {}", k);
                return;
            }
        };
        let Some(cents) = to_cents(amount) else {
            println!("ERROR line {}", k);
            return;
        };
        *balances.entry(account.to_string()).or_insert(0) += sign * cents;
    }

    let mut entries: Vec<(String, i128)> = balances.into_iter().collect();
    entries.sort_by(|a, b| b.1.cmp(&a.1).then_with(|| a.0.as_bytes().cmp(b.0.as_bytes())));

    let mut out = String::new();
    let mut total: i128 = 0;
    for (account, balance) in &entries {
        out.push_str(&format!("{} {}\n", account, format_cents(*balance)));
        total += balance;
    }
    out.push_str(&format!("TOTAL {}\n", format_cents(total)));
    print!("{}", out);
}

